//! 🧪️ Original in-place payload bindings, pages and ledger conserve actual heap through every frontier.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_in_place_payload_builder_preserves_fixed_grants_source_pages_and_all_cancellation_frontiers(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};let cancel=root_cancel_token();let(_,warm)=observe(||{let probe=vec![7u8;37];std::hint::black_box(&probe);drop(probe);});assert_eq!(warm,(37,37));
 for bytes in law["byteLengths"].as_array().unwrap(){let bytes=bytes.as_u64().unwrap()as usize;let source:Vec<u8>=(0..bytes).map(|i|(i%251)as u8).collect();let source_pointer=source.as_ptr();for cut in [0,1,2,3,5,9,usize::MAX]{let operation=OperationId(99201);let generation=Generation(3);let((mut authority,admission),ledger_birth)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!((admission.retained_capacity_bytes,admission.released_bytes),ledger_birth);assert!(admission.fits(grant));assert_eq!(admission.copied_bytes,law["metadataCopyBytes"].as_u64().unwrap()as usize);let original_ledger_pointer=Arc::as_ptr(authority.original().unwrap());let mut builder=RetainedPayloadBuilder::new(JobPayloadStream::Preview);let owner_pointer=std::ptr::addr_of!(builder);let mut born=ledger_birth.0;let mut released=ledger_birth.1;let mut sequence=0;let mut cursor=0;let mut turns=0;let mut sealed=false;
 while turns<cut&&!sealed{let demand=if !builder.is_initialized(){builder.initialization_demand()}else if cursor<bytes{builder.append_demand(grant).unwrap()}else{RetirementDemand{depth:1,..Default::default()}};if builder.is_initialized()&&cursor==0&&bytes>0{assert_eq!(demand.copy_bytes,usize::from(demand.capacity_bytes==0));}let page_pointer=builder.original().and_then(|p|p.page(0)).map(|page|page.as_ptr());for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:0,..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let mut receipt=RetainedCloneProgress::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let cursor_before=cursor;let(_,heap)=observe(||{if !builder.is_initialized(){builder.advance_initialization(&mut cx).unwrap()}else if cursor<bytes{builder.append_original(&mut cx,&source,&mut cursor).unwrap()}else{builder.seal(&mut cx).unwrap()}});assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());assert_eq!(cursor,cursor_before);assert_eq!(std::ptr::addr_of!(builder),owner_pointer);assert_eq!(builder.original().and_then(|p|p.page(0)).map(|page|page.as_ptr()),page_pointer);assert_eq!(source.as_ptr(),source_pointer);}let mut receipt=RetainedCloneProgress::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(_,heap)=observe(||{if !builder.is_initialized(){builder.advance_initialization(&mut cx).unwrap()}else if cursor<bytes{builder.append_original(&mut cx,&source,&mut cursor).unwrap()}else{sealed=builder.seal(&mut cx).unwrap();sealed}});let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap);assert_eq!(progress.copied_items,1);born+=heap.0;released+=heap.1;turns+=1;assert!(turns<100000);assert_eq!(source.as_ptr(),source_pointer);assert_eq!(Arc::as_ptr(authority.original().unwrap()),original_ledger_pointer);}
 if sealed{let payload=builder.published().unwrap();let mut offset=0;for index in 0..payload.page_count(){let page=payload.page(index).unwrap();assert_eq!(page,&source[offset..offset+page.len()]);offset+=page.len();}assert_eq!(offset,bytes);assert_eq!(payload.len(),bytes);}
 while !builder.terminal_is_empty(){let demand=builder.retirement_demands().unwrap();let page_pointer=builder.original().and_then(|p|p.page(0)).map(|p|p.as_ptr());for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(done,heap)=observe(||builder.close_step(&mut cx).unwrap());assert!(!done);assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());assert_eq!(builder.original().and_then(|p|p.page(0)).map(|p|p.as_ptr()),page_pointer);assert_eq!(source.as_ptr(),source_pointer);}let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(_,heap)=observe(||builder.close_step(&mut cx).unwrap());assert!(cx.retained_progress().fits(grant));assert_eq!((cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes),heap);born+=heap.0;released+=heap.1;}
 let(step,heap)=observe(||authority.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;let(_,heap)=observe(||drop(builder));assert_eq!(heap,(0,0));assert_eq!(born,released);assert!(authority.terminal_is_empty());let(_,authority_drop)=observe(||drop(authority));assert_eq!(authority_drop,(0,0));assert_eq!(source.as_ptr(),source_pointer);eprintln!("[DEBUG] actual original in-place payload bytes={bytes} cancellation={cut} initAppendSealTurns={turns} source={source_pointer:p} owner={owner_pointer:p} cursor={cursor} physical={released} pageBytes={JOB_PAYLOAD_PAGE_BYTES} terminalDrop0 fixedBody4096");}}
}

#[test]
fn original_payload_authority_admits_once_and_borrowed_contexts_preserve_original_ledger_and_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};let operation=OperationId(99203);let generation=Generation(7);let cancel=root_cancel_token();let(_,warm)=observe(||drop(vec![0u8;37]));assert_eq!(warm,(37,37));let demand=JobPayloadAuthority::admission_demand();
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe(||JobPayloadAuthority::admit(operation,generation,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));}
 let((mut authority,birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert!(birth.fits(grant));assert_eq!(birth.copied_bytes,demand.copy_bytes);assert_eq!(birth.copied_bytes,law["metadataCopyBytes"].as_u64().unwrap()as usize);assert_eq!((birth.retained_capacity_bytes,birth.released_bytes),heap);let original_pointer=Arc::as_ptr(authority.original().unwrap());let original_count=Arc::strong_count(authority.original().unwrap());let mut sequence=0;
 for turn in 0..17{let prior=RetainedCloneProgress{copied_bytes:23,..Default::default()};let mut recipient=prior;let(_,heap)=observe(||{let mut context=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut recipient,&authority).unwrap();assert_eq!(Arc::as_ptr(&context.payload_ledger),original_pointer);assert_eq!(Arc::strong_count(&context.payload_ledger),original_count);assert_eq!(context.retained_grant().maximum_copy_bytes,grant.maximum_copy_bytes-23);context.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()}).unwrap();assert_eq!(context.retained_grant().maximum_items,0);assert_eq!(context.retained_grant().maximum_copy_bytes,grant.maximum_copy_bytes-64);drop(context);});assert_eq!(heap,(0,0));assert_eq!(recipient,RetainedCloneProgress{copied_items:1,copied_bytes:64,..Default::default()});assert_eq!(Arc::as_ptr(authority.original().unwrap()),original_pointer);assert_eq!(Arc::strong_count(authority.original().unwrap()),original_count);eprintln!("[DEBUG] actual borrowed original payload authority turn={turn} ledger={original_pointer:p} originalLeaseCount={original_count} copy64 sameCallerRecipient noHeap contextDrop0");}
 let demand=authority.retirement_demands();for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,heap)=observe(||authority.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(Arc::as_ptr(authority.original().unwrap()),original_pointer);}
 let(step,heap)=observe(||authority.close_step(grant).unwrap());assert!(matches!(step,RetainedCloneStep::Complete(_)));assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);assert_eq!(step.progress().copied_bytes,demand.copy_bytes);assert_eq!(birth.retained_capacity_bytes,step.progress().released_bytes);let(_,heap)=observe(||drop(authority));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original payload authority paidCopy={} originalPhysical={} separateUniqueRelease={} terminalDrop0 fixedCopy4096",birth.copied_bytes,birth.retained_capacity_bytes,step.progress().released_bytes);
}

#[test]
fn original_payload_pages_preserve_narrow_capacity_exact_extents_and_native_conservation(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📏️extent/🧫️fixtures/🔣️.json")).unwrap();let p=law["policy"].as_array().unwrap();let grant=RetainedCloneGrant{maximum_items:p[0].as_u64().unwrap()as usize,maximum_copy_bytes:p[1].as_u64().unwrap()as usize,maximum_capacity_bytes:p[2].as_u64().unwrap()as usize,maximum_release_bytes:p[3].as_u64().unwrap()as usize,maximum_depth:p[4].as_u64().unwrap()as usize};let source:Vec<u8>=(0..law["sourceBytes"].as_u64().unwrap()as usize).map(|i|(i%251)as u8).collect();let pointer=source.as_ptr();let operation=OperationId(99204);let generation=Generation(8);let cancel=root_cancel_token();
 for cut in[0,258,259,800,usize::MAX]{let((mut authority,birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!(heap,(birth.retained_capacity_bytes,0));let mut born=heap.0;let mut released=0;let mut builder=RetainedPayloadBuilder::new(JobPayloadStream::Preview);let mut cursor=0;let mut sequence=0;let mut turns=0;let mut copied=0;while turns<cut&&builder.published().is_none(){let demand=if !builder.is_initialized(){builder.initialization_demand()}else if cursor<source.len(){builder.append_demand(grant).unwrap()}else{RetirementDemand{depth:1,..Default::default()}};for denied in[Some(RetainedCloneGrant{maximum_items:0,..grant}),Some(RetainedCloneGrant{maximum_depth:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:0,..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:0,..grant})].into_iter().flatten(){let before=cursor;let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(_,heap)=observe(||{if !builder.is_initialized(){builder.advance_initialization(&mut cx).unwrap()}else if cursor<source.len(){builder.append_original(&mut cx,&source,&mut cursor).unwrap()}else{builder.seal(&mut cx).unwrap()}});assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());assert_eq!(cursor,before);}let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(_,heap)=observe(||{if !builder.is_initialized(){builder.advance_initialization(&mut cx).unwrap()}else if cursor<source.len(){builder.append_original(&mut cx,&source,&mut cursor).unwrap()}else{builder.seal(&mut cx).unwrap()}});let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));if heap.0>0{assert_eq!(heap.0,8192);assert_eq!(progress.copied_bytes,0);}copied+=progress.copied_bytes;born+=heap.0;released+=heap.1;turns+=1;assert!(turns<10000);assert_eq!(source.as_ptr(),pointer);}
 assert_eq!(authority.original().unwrap().process_share_bytes(),builder.original().map_or(0,|p|p.pages.iter().flatten().map(|p|p.source.allocated_capacity_bytes()).sum()));if let Some(payload)=builder.published(){assert_eq!(copied,source.len());let mut offset=0;for page in payload.pages.iter().flatten(){assert_eq!(page.source.allocated_capacity_bytes(),8192);assert_eq!(page.bytes(),&source[offset..offset+page.length]);offset+=page.length;}assert_eq!(offset,source.len());assert_eq!(payload.page_count(),3);}
 while !builder.terminal_is_empty(){let demand=builder.retirement_demands().unwrap();if demand.release_bytes>0{let(step,heap)=observe(||builder.close_step_granted(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}let(step,heap)=observe(||builder.close_step_granted(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(step.progress().copied_bytes,0);assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;}assert_eq!(authority.original().unwrap().process_share_bytes(),0);let(step,heap)=observe(||authority.close_step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;assert_eq!(born,released);let(_,heap)=observe(||{drop(builder);drop(authority);});assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original narrow pages cancellation={cut} turns={turns} copy={copied} physical={born} released={released} original17copy8192capacity source={pointer:p} terminalDrop0");}
}
